// Minimal local stub QR generator (placeholder).
// Replace this file with the real qrcode.min.js library for production.
(function (window) {
  window.QRCode = window.QRCode || {};
  // Simple toCanvas stub: draws placeholder text so UI remains usable
  window.QRCode.toCanvas = function (canvas, text, options, cb) {
    try {
      var ctx = canvas.getContext && canvas.getContext("2d");
      if (!ctx) throw new Error("Canvas not supported");
      // draw white background
      ctx.fillStyle =
        (options && options.color && options.color.light) || "#ffffff";
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      // draw placeholder border
      ctx.strokeStyle =
        (options && options.color && options.color.dark) || "#000000";
      ctx.lineWidth = 4;
      ctx.strokeRect(2, 2, canvas.width - 4, canvas.height - 4);
      // draw short text
      ctx.fillStyle = ctx.strokeStyle;
      ctx.font = "12px sans-serif";
      var short = text ? String(text).slice(0, 24) : "QR";
      ctx.fillText("QR PLACEHOLDER", 10, 30);
      ctx.font = "10px monospace";
      ctx.fillText(short, 10, canvas.height - 10);
      if (typeof cb === "function") cb(null);
    } catch (err) {
      if (typeof cb === "function") cb(err);
    }
  };
})(window);
